function combine(n, k) {
  const result = [];
  const path = [];
  const build = (start) => {
    if (path.length === k) {
      result.push([...path]);
      return;
    }
    const last = n - (k - path.length) + 1;    // beyond this, too few numbers are left
    for (let x = start; x <= last; x++) {
      path.push(x);
      build(x + 1);
      path.pop();
    }
  };
  build(1);
  return result;
}

def combine(n, k):
    result, path = [], []

    def build(start):
        if len(path) == k:
            result.append(path[:])
            return
        last = n - (k - len(path)) + 1    # beyond this, too few numbers are left
        for x in range(start, last + 1):
            path.append(x)
            build(x + 1)
            path.pop()

    build(1)
    return result

